  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","value","caption","accentIndex","stagger","coils","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  value: "3.4×",
  caption: "Least sag under the same load",
  accentIndex: 4,
  stagger: 3,
  coils: 11,
  accent: "#3B5BFD",
  fontFamily: "Schibsted Grotesk",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type SpringBarsElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof SpringBarsBase>;

const SpringBarsInner = forwardRef<
  HTMLDivElement,
  SpringBarsElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<SpringBars>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <SpringBarsBase
          {...(componentProps as unknown as ComponentProps<typeof SpringBarsBase>)}
        />
      </div>
    </Sequence>
  );
});

export const SpringBars = Interactive.withSchema({
  Component: SpringBarsInner,
  componentName: "<SpringBars>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
